def get_all_flat_list():
    flat_data = []
    for xaafada, nodes in hargeisa_complete_xaafadaha_db.items():
        for node in nodes:
            flat_data.append({
                'xaafada': xaafada,
                'laanta': node['laanta'],
                'tilmaanta': node['tilmaanta'],
                'latitude': node['latitude'],
                'longitude': node['longitude']
            })
    return flat_data
